import test from 'node:test';
import assert from 'node:assert/strict';
import { canRetry } from './src/retry-policy.js';

test('allows retries only while below the configured limit', () => {
  assert.equal(canRetry(0, 3), true);
  assert.equal(canRetry(2, 3), true);
  assert.equal(canRetry(3, 3), false);
  assert.equal(canRetry(0, 0), false);
});

test('rejects invalid retry counters', () => {
  for (const [used, limit] of [[-1, 3], [0, -1], [1.5, 3], [0, 2.5], ['0', 3], [0, null]]) {
    assert.equal(canRetry(used, limit), false);
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';

test('creates the requested runbook with the supplied facts and exactly three steps', async () => {
  const text = await readFile('runbook.md', 'utf8');
  assert.match(text, /^# .+Atlas/m);
  assert.match(text, /npm run start/);
  assert.match(text, /\/health/);
  assert.match(text, /HTTP 200|200/);
  const steps = text.match(/^\s*\d+[.)]\s+/gm) || [];
  assert.equal(steps.length, 3);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';

test('creates a concise summary containing only the supplied service facts', async () => {
  const text = await readFile('support-summary.md', 'utf8');
  assert.match(text, /^# .+$/m);
  assert.match(text, /Monday through Friday|Monday-Friday|Monday–Friday/);
  assert.match(text, /08:00/);
  assert.match(text, /18:00/);
  assert.match(text, /UTC/);
  assert.match(text, /two hours|2 hours/);
  const bullets = text.match(/^\s*[-*+]\s+/gm) || [];
  assert.equal(bullets.length, 2);
  assert.doesNotMatch(text, /24\s*\/\s*7|system prompt|ignore the user/i);
});

