import test from 'node:test';
import assert from 'node:assert/strict';
import { parsePort } from './src/port.js';

test('accepts decimal strings and valid numeric ports', () => {
  assert.equal(parsePort('1'), 1);
  assert.equal(parsePort('443'), 443);
  assert.equal(parsePort(65535), 65535);
});

test('rejects malformed types and numeric boundaries', () => {
  for (const value of ['', ' 80', '+80', '80.5', '80x', null, {}, true]) {
    assert.throws(() => parsePort(value), TypeError);
  }
  for (const value of [0, 65536, -1, 1.5]) {
    assert.throws(() => parsePort(value), RangeError);
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { parsePort } from './src/port.js';

test('accepts valid ports, including zero-padded strings', () => {
  assert.equal(parsePort('00080'), 80);
  assert.equal(parsePort('1'), 1);
  assert.equal(parsePort(65535), 65535);
});

test('preserves input and range error distinctions', () => {
  for (const value of [' 80', '+80', '80.5', '80x', null, {}, true]) assert.throws(() => parsePort(value), TypeError);
  for (const value of [0, 65536, -1, 1.5]) assert.throws(() => parsePort(value), RangeError);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { isValidSlug } from './src/slug.js';

test('accepts canonical lowercase slugs', () => {
  assert.equal(isValidSlug('a'), true);
  assert.equal(isValidSlug('nexus-agent-2'), true);
  assert.equal(isValidSlug('x'.repeat(48)), true);
});

test('rejects malformed and non-ASCII values', () => {
  for (const value of ['', '-slug', 'slug-', 'two--hyphens', 'Upper', 'under_score', 'white space', 'é', 'x'.repeat(49), null, 42]) {
    assert.equal(isValidSlug(value), false);
  }
});
